`package sample
import "testing"
import "testing/synctest"
func TestTurn(t *testing.T) {
 synctest.Test(t, func(t *testing.T) {
  var x [2]struct { turn int }
  i := 0
  x[i].turn = 1
  { i := 1; use(x[i].turn) }
 })
}
`

`package sample
import "testing"
import "testing/synctest"
func TestTargets(t *testing.T) {
 synctest.Test(t, func(t *testing.T) {
  var x struct { field int }
  var a [2]int
  x.field = 1
  a[0] = 1
  use(x.field, a[0])
 })
}
`
